// ── Types ──────────────────────────────────────────────────────────────────
export interface KPIData {
  label: string;
  value: number;
  previousValue: number;
  unit: string;
  trend: "up" | "down" | "stable";
  trendLabel: string;
  description: string;
  indicatorCode?: string;
}

export interface TimeSeriesPoint {
  year: number;
  value: number;
}

export interface RegionalValue {
  region: string;
  value: number;
}

export interface IndicatorData {
  code: string;
  label: string;
  unit: string;
  national: TimeSeriesPoint[];
  regional: RegionalValue[];
  regionalOld?: RegionalValue[];
  isNationalOnly?: boolean;
  regionalIsRate?: boolean;
  source?: string;
}

export interface ModuleData {
  name: string;
  description: string;
  kpis: KPIData[];
  indicators: IndicatorData[];
}

