// ── Helpers ────────────────────────────────────────────────────────────────
function genTimeSeries(
  startYear: number,
  endYear: number,
  startVal: number,
  endVal: number,
  volatility = 0.02
): TimeSeriesPoint[] {
  const pts: TimeSeriesPoint[] = [];
  const n = endYear - startYear + 1;
  for (let i = 0; i < n; i++) {
    const t = i / (n - 1);
    const base = startVal + (endVal - startVal) * t;
    const noise = base * (Math.sin(i * 2.7) * volatility);
    pts.push({
      year: startYear + i,
      value: Math.round((base + noise) * 100) / 100,
    });
  }
  return pts;
}

function genRegional(baseValue: number, spread = 0.3, isInteger = false): RegionalValue[] {
  const multipliers = [
    1.35, 0.85, 0.92, 1.28, 0.72, 1.45, 0.88, 0.65, 0.95, 0.58, 0.42, 0.38,
  ];
  return REGIONS.map((region, i) => ({
    region,
    value: isInteger
      ? Math.round(baseValue * multipliers[i] * (0.9 + Math.random() * 0.2))
      : Math.round(baseValue * multipliers[i] * (0.9 + Math.random() * 0.2) * 100) / 100,
  })).sort((a, b) => b.value - a.value);
}

function genRegionalOld(baseValue: number, spread = 0.3, isInteger = false): RegionalValue[] {
  const multipliers = [
    1.35, 0.85, 0.92, 1.28, 0.72, 1.45, 0.88, 0.65, 0.95, 0.58, 0.42, 0.38,
    1.15, 0.78, 1.05, 0.68,
  ];
  return REGIONS_OLD.map((region, i) => ({
    region,
    value: isInteger
      ? Math.round(baseValue * multipliers[i] * (0.9 + Math.random() * 0.2))
      : Math.round(baseValue * multipliers[i] * (0.9 + Math.random() * 0.2) * 100) / 100,
  })).sort((a, b) => b.value - a.value);
}

