function genRegionalFromShares(shares: Record<string, number> | [string, number][], nationalValue: number, isInteger = false): RegionalValue[] {
  const entries: [string, number][] = Array.isArray(shares)
    ? shares
    : (Object.entries(shares) as [string, number][]);
  return entries.map(([region, pct]) => ({
    region,
    value: isInteger
      ? Math.round(nationalValue * pct / 100)
      : Math.round(nationalValue * pct / 100 * 100) / 100,
  })).sort((a, b) => b.value - a.value);
}

// Use when values are already rates (NOT shares of a total)
// E.g. poverty rate 16.8% in Béni Mellal — use as-is, don't multiply by national
function genRegionalDirect(rates: Record<string, number>): RegionalValue[] {
  return Object.entries(rates).map(([region, rate]) => ({
    region,
    value: Math.round(rate * 100) / 100,
  })).sort((a, b) => b.value - a.value);
}

function ts(data: [number, number][]): TimeSeriesPoint[] {
  return data.map(([year, value]) => ({ year, value }));
}

// ── Utility Functions ──────────────────────────────────────────────────────
export function getRegionsForYear(year: number): readonly string[] {
  return year < 2015 ? REGIONS_OLD : REGIONS;
}

export function playChangeSound() {
  if (typeof window === "undefined") return;
  try {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.type = "sine";
    osc.frequency.setValueAtTime(800, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.15);
  } catch {}
}

